  1	import { configDir, deviceFlow, forgetSession, needsRenewal, readSession, renew, writeSession, type Session } from "@runlog/session";
  2	
  3	export interface Account {
  4	  apiBase: string;
  5	}
  6	
  7	/**
  8	 * The address without its trailing slash.
  9	 *
 10	 * Every caller joins a path onto it, and a streamer who pastes the address
 11	 * out of a browser bar brings the slash with them - which would ask for
 12	 * `//api/...` and dial `//ws`. Trimmed wherever the base is used, rather
 13	 * than trusted to have been cleaned on the way in.
 14	 */
 15	export function normalizeBase(apiBase: string): string {
 16	  return apiBase.trim().replace(/\/+$/, "");
 17	}
 18	
 19	/**
 20	 * The deck's session, kept in a file of the plugin's own.
 21	 *
 22	 * Not in Stream Deck's global settings: those are handed to the property
 23	 * inspector, which is a web view, and a refresh token is the one thing
 24	 * this plugin holds that must never be. The CLI keeps its session the
 25	 * same way, in the same directory tree, under a different name.
 26	 */
 27	export function sessionDir(): string {
 28	  return configDir("runlog-deck");
 29	}
 30	
 31	// A test's own directory, so a test run never renews the real rotating
 32	// token and never collides with the CLI's. Unset outside of tests.
 33	let dirOverride: string | null = null;
 34	export function __setSessionDirForTests(dir: string | null): void {
 35	  dirOverride = dir;
 36	  renewing = null;
 37	}
 38	function dir(): string {
 39	  return dirOverride ?? sessionDir();
 40	}
 41	
 42	export function loadSession(): Session | null {
 43	  return readSession(dir());
 44	}
 45	
 46	export function signOut(): void {
 47	  forgetSession(dir());
 48	}
 49	
 50	async function clientOf(account: Account): Promise<{ clientId: string; issuer: string }> {
 51	  const res = await fetch(`${normalizeBase(account.apiBase)}/api/auth/deck`);
 52	  const body = (await res.json()) as { clientId?: string | null; issuer?: string };
 53	  if (!body.clientId) throw new Error("this copy of Runlog has no sign-in for a deck");
 54	  return { clientId: body.clientId, issuer: body.issuer ?? "https://api.workos.com" };
 55	}
 56	
 57	export async function signIn(account: Account, say: (line: string) => void, open: (url: string) => void): Promise<Session> {
 58	  const { clientId, issuer } = await clientOf(account);
 59	  const session = await deviceFlow(clientId, issuer, {
 60	    fetch: (input, init) => fetch(input, init),
 61	    sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
 62	    say,
 63	    open,
 64	    now: () => Date.now(),
 65	  });
 66	  writeSession(dir(), session);
 67	  return session;
 68	}
 69	
 70	/**
 71	 * The renewal in flight, if there is one.
 72	 *
 73	 * WorkOS rotates the refresh token, so a second POST with the token the
 74	 * first one just spent is refused - and the deck's two callers, the socket
 75	 * opening and the snapshot fetch, ask for a bearer at the same moment. They
 76	 * share the one renewal instead: whoever asks first starts it, everyone
 77	 * else waits on it, and the file is written once.
 78	 */
 79	let renewing: Promise<string | null> | null = null;
 80	
 81	/** The bearer to send, renewed first when it is about to lapse; null means sign in. */
 82	export function bearer(_account: Account): Promise<string | null> {
 83	  const session = loadSession();
 84	  if (!session) return Promise.resolve(null);
 85	  if (!needsRenewal(session, Date.now())) return Promise.resolve(session.accessToken);
 86	  renewing ??= renew(session)
 87	    .then((renewed) => {
 88	      writeSession(dir(), renewed);
 89	      return renewed.accessToken;
 90	    })
 91	    .catch(() => {
 92	      // A refresh the issuer refused is a session that is over. Leave the
 93	      // file so a retry after a network blip is not a full sign-in, and
 94	      // let the caller read the null as "Sign in again".
 95	      return null;
 96	    })
 97	    .finally(() => {
 98	      renewing = null;
 99	    });
100	  return renewing;
101	}

