  1	import { mkdtempSync } from "node:fs";
  2	import { tmpdir } from "node:os";
  3	import { join } from "node:path";
  4	import { readSession, writeSession } from "@runlog/session";
  5	import { afterEach, describe, expect, it, vi } from "vitest";
  6	import { __setSessionDirForTests, bearer, loadSession, normalizeBase, signIn, signOut } from "./session.ts";
  7	
  8	const jwt = (exp: number) => `h.${Buffer.from(JSON.stringify({ exp })).toString("base64url")}.s`;
  9	
 10	function useTempDir(): string {
 11	  const dir = mkdtempSync(join(tmpdir(), "runlog-deck-session-"));
 12	  __setSessionDirForTests(dir);
 13	  return dir;
 14	}
 15	
 16	afterEach(() => {
 17	  __setSessionDirForTests(null);
 18	  vi.unstubAllGlobals();
 19	});
 20	
 21	describe("the deck's session", () => {
 22	  it("signs in through the device flow against the deck's own client", async () => {
 23	    useTempDir();
 24	    const fetch = vi.fn(async (url: string) => {
 25	      if (String(url).endsWith("/api/auth/deck"))
 26	        return new Response(JSON.stringify({ clientId: "client_deck", issuer: "https://api.workos.com" }));
 27	      if (String(url).includes("/authorize/device"))
 28	        return new Response(
 29	          JSON.stringify({ device_code: "d", user_code: "ABCD-EFGH", verification_uri: "https://x/y", interval: 0, expires_in: 60 }),
 30	        );
 31	      return new Response(
 32	        JSON.stringify({
 33	          access_token: "a." + Buffer.from(JSON.stringify({ exp: 9999999999 })).toString("base64url") + ".s",
 34	          refresh_token: "r",
 35	        }),
 36	      );
 37	    });
 38	    vi.stubGlobal("fetch", fetch);
 39	    const said: string[] = [];
 40	    const s = await signIn(
 41	      { apiBase: "https://api.test" },
 42	      (l) => said.push(l),
 43	      () => {},
 44	    );
 45	    expect(s.clientId).toBe("client_deck");
 46	    expect(said.join("\n")).toContain("ABCD-EFGH");
 47	  });
 48	
 49	  it("renews near expiry and saves the rotated refresh token, not just the access token it returns", async () => {
 50	    const dir = useTempDir();
 51	    writeSession(dir, {
 52	      clientId: "client_deck",
 53	      issuer: "https://api.workos.test",
 54	      accessToken: "stale",
 55	      refreshToken: "r1",
 56	      expiresAt: new Date(0).toISOString(),
 57	    });
 58	    const fetch = vi.fn(async () => new Response(JSON.stringify({ access_token: jwt(9999999999), refresh_token: "r2" })));
 59	    vi.stubGlobal("fetch", fetch);
 60	
 61	    const token = await bearer({ apiBase: "https://api.test" });
 62	
 63	    expect(token).toBe(jwt(9999999999));
 64	    // The proof that matters: a fresh read off disk sees the rotated
 65	    // refresh token, not the one the session started with. WorkOS rotates
 66	    // it on every renewal, so a renewal that is not written back kills
 67	    // the next one.
 68	    expect(readSession(dir)?.refreshToken).toBe("r2");
 69	  });
 70	
 71	  it("renews once when two callers ask at the same moment, since the refresh token rotates", async () => {
 72	    const dir = useTempDir();
 73	    writeSession(dir, {
 74	      clientId: "client_deck",
 75	      issuer: "https://api.workos.test",
 76	      accessToken: "stale",
 77	      refreshToken: "r1",
 78	      expiresAt: new Date(0).toISOString(),
 79	    });
 80	    // The second POST would carry the token the first one just spent, and
 81	    // WorkOS refuses that - which is the deck thrown to "Sign in again"
 82	    // for nothing. So this counts the calls, not just the answers.
 83	    const fetch = vi.fn(async () => new Response(JSON.stringify({ access_token: jwt(9999999999), refresh_token: "r2" })));
 84	    vi.stubGlobal("fetch", fetch);
 85	
 86	    const [first, second] = await Promise.all([bearer({ apiBase: "https://api.test" }), bearer({ apiBase: "https://api.test" })]);
 87	
 88	    expect(fetch).toHaveBeenCalledTimes(1);
 89	    expect(first).toBe(jwt(9999999999));
 90	    expect(second).toBe(first);
 91	    expect(readSession(dir)?.refreshToken).toBe("r2");
 92	  });
 93	
 94	  it("starts a fresh renewal after the shared one settles", async () => {
 95	    const dir = useTempDir();
 96	    writeSession(dir, {
 97	      clientId: "client_deck",
 98	      issuer: "https://api.workos.test",
 99	      accessToken: "stale",
100	      refreshToken: "r1",
101	      expiresAt: new Date(0).toISOString(),
102	    });
103	    // The token this hands back has already lapsed, so the second ask
104	    // needs a renewal of its own: the in-flight promise is shared, not
105	    // cached.
106	    const fetch = vi.fn(async () => new Response(JSON.stringify({ access_token: jwt(1), refresh_token: "r2" })));
107	    vi.stubGlobal("fetch", fetch);
108	
109	    await bearer({ apiBase: "https://api.test" });
110	    await bearer({ apiBase: "https://api.test" });
111	
112	    expect(fetch).toHaveBeenCalledTimes(2);
113	  });
114	
115	  it("leaves the file alone when a renewal is refused, since a network blip is not a sign-out", async () => {
116	    const dir = useTempDir();
117	    writeSession(dir, {
118	      clientId: "client_deck",
119	      issuer: "https://api.workos.test",
120	      accessToken: "stale",
121	      refreshToken: "r1",
122	      expiresAt: new Date(0).toISOString(),
123	    });
124	    const fetch = vi.fn(async () => new Response(JSON.stringify({ error: "invalid_grant" }), { status: 400 }));
125	    vi.stubGlobal("fetch", fetch);
126	
127	    const token = await bearer({ apiBase: "https://api.test" });
128	
129	    expect(token).toBeNull();
130	    expect(readSession(dir)?.refreshToken).toBe("r1");
131	  });
132	
133	  it("forgets the session on sign-out; bearer then asks to sign in again", async () => {
134	    const dir = useTempDir();
135	    writeSession(dir, {
136	      clientId: "client_deck",
137	      issuer: "https://api.workos.test",
138	      accessToken: "a",
139	      refreshToken: "r",
140	      expiresAt: new Date(Date.now() + 3_600_000).toISOString(),
141	    });
142	
143	    signOut();
144	
145	    expect(loadSession()).toBeNull();
146	    expect(await bearer({ apiBase: "https://api.test" })).toBeNull();
147	    expect(readSession(dir)).toBeNull();
148	  });
149	});
150	
151	// A streamer pastes the address out of a browser bar, slash and all, and
152	// every caller joins a path onto it.
153	describe("the address a path is joined onto", () => {
154	  it("loses its trailing slashes and its whitespace", () => {
155	    expect(normalizeBase("https://runlog.dev.scrthq.com/")).toBe("https://runlog.dev.scrthq.com");
156	    expect(normalizeBase("  https://runlog.scrthq.com///  ")).toBe("https://runlog.scrthq.com");
157	  });
158	  it("leaves an address that is already clean alone", () => {
159	    expect(normalizeBase("https://runlog.scrthq.com")).toBe("https://runlog.scrthq.com");
160	    expect(normalizeBase("http://localhost:5173")).toBe("http://localhost:5173");
161	  });
162	});

