  1	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
  2	
  3	// As in `roll.test.ts`: `base.ts` reaches the store and the wire through
  4	// `../plugin.ts`, which registers every action and opens a socket. Here the
  5	// store is a fake whose subscribers this file drives by hand, so a verdict
  6	// arriving - or never arriving - is something a test can stage.
  7	const mock = vi.hoisted(() => ({
  8	  state: { on: true, flash: null } as { on: boolean; flash: { ref: string; ok: boolean } | null },
  9	  listeners: new Set<(s: unknown) => void>(),
 10	  ref: "r1" as string | null,
 11	  pressed: [] as unknown[],
 12	}));
 13	vi.mock("../plugin.ts", () => ({
 14	  store: {
 15	    get state() {
 16	      return mock.state;
 17	    },
 18	    dispatch: () => {},
 19	    subscribe: (fn: (s: unknown) => void) => {
 20	      mock.listeners.add(fn);
 21	      return () => mock.listeners.delete(fn);
 22	    },
 23	  },
 24	  sayWho: async () => {},
 25	  wire: {
 26	    press: (p: unknown) => {
 27	      mock.pressed.push(p);
 28	      return mock.ref;
 29	    },
 30	  },
 31	}));
 32	
 33	const { RunlogAction } = await import("./base.ts");
 34	
 35	/** An action that does nothing but press, so only `send` is under test. */
 36	class Probe extends RunlogAction {
 37	  face() {
 38	    return { title: "Probe", tone: "live" as const };
 39	  }
 40	  async press(action: unknown): Promise<void> {
 41	    await this.send(action as never, { press: "undo" });
 42	  }
 43	}
 44	
 45	/** What the deck was told: "ok" for the checkmark, "alert" for the cross. */
 46	function key(): {
 47	  id: string;
 48	  told: string[];
 49	  isKey: () => boolean;
 50	  isDial: () => boolean;
 51	  showOk: () => Promise<void>;
 52	  showAlert: () => Promise<void>;
 53	} {
 54	  const told: string[] = [];
 55	  return {
 56	    id: "a1",
 57	    told,
 58	    isKey: () => true,
 59	    isDial: () => false,
 60	    showOk: async () => {
 61	      told.push("ok");
 62	    },
 63	    showAlert: async () => {
 64	      told.push("alert");
 65	    },
 66	  };
 67	}
 68	
 69	/** The store moving on, as the socket would move it. */
 70	function emit(state: { on: boolean; flash: { ref: string; ok: boolean } | null }): void {
 71	  mock.state = state;
 72	  for (const fn of mock.listeners) fn(state);
 73	}
 74	
 75	describe("a press waiting on the server's verdict", () => {
 76	  beforeEach(() => {
 77	    vi.useFakeTimers();
 78	    mock.state = { on: true, flash: null };
 79	    mock.listeners.clear();
 80	    mock.pressed = [];
 81	    mock.ref = "r1";
 82	  });
 83	  afterEach(() => vi.useRealTimers());
 84	
 85	  it("shows the checkmark when the answer is yes", async () => {
 86	    const k = key();
 87	    await new Probe().press(k);
 88	    emit({ on: true, flash: { ref: "r1", ok: true } });
 89	    expect(k.told).toEqual(["ok"]);
 90	    expect(mock.listeners.size).toBe(0);
 91	  });
 92	
 93	  it("shows the alert when the server refuses the press", async () => {
 94	    const k = key();
 95	    await new Probe().press(k);
 96	    emit({ on: true, flash: { ref: "r1", ok: false } });
 97	    expect(k.told).toEqual(["alert"]);
 98	    expect(mock.listeners.size).toBe(0);
 99	  });
100	
101	  it("ignores a verdict for somebody else's press", async () => {
102	    const k = key();
103	    await new Probe().press(k);
104	    emit({ on: true, flash: { ref: "r2", ok: true } });
105	    expect(k.told).toEqual([]);
106	    emit({ on: true, flash: { ref: "r1", ok: true } });
107	    expect(k.told).toEqual(["ok"]);
108	  });
109	
110	  it("alerts when no verdict arrives at all, rather than saying nothing", async () => {
111	    const k = key();
112	    await new Probe().press(k);
113	    expect(k.told).toEqual([]);
114	    await vi.advanceTimersByTimeAsync(5000);
115	    expect(k.told).toEqual(["alert"]);
116	    expect(mock.listeners.size).toBe(0);
117	  });
118	
119	  it("says nothing when the deck goes off under the press", async () => {
120	    const k = key();
121	    await new Probe().press(k);
122	    emit({ on: false, flash: null });
123	    await vi.advanceTimersByTimeAsync(5000);
124	    // The streamer pressed Disconnect; a cross on the key would be
125	    // reporting a failure that is really an instruction being obeyed.
126	    expect(k.told).toEqual([]);
127	    expect(mock.listeners.size).toBe(0);
128	  });
129	
130	  it("alerts at once when there is no wire to press", async () => {
131	    mock.ref = null;
132	    const k = key();
133	    await new Probe().press(k);
134	    expect(k.told).toEqual(["alert"]);
135	    expect(mock.listeners.size).toBe(0);
136	  });
137	});

