 37	 * `Profiles` entry without the `.streamDeckProfile` file behind it, and
 38	 * that file can only come from exporting the laid-out profile in the
 39	 * Stream Deck app. Once `profiles/Runlog.streamDeckProfile` exists, the
 40	 * manifest gains `Profiles: [{ Name: "Runlog", DeviceType: 0, Readonly: false, DontAutoSwitchWhenInstalled: true }]`.
 41	 * Until then the switch below fails quietly, which is correct for a copy
 42	 * without the profile.
 43	 */
 44	const PROFILE_NAME = "Runlog";
 45	
 46	/**
 47	 * Attaching switches the deck to the Runlog profile. It is the one
 48	 * attach feedback that works on every model, a six-key Mini included,
 49	 * and it puts the run's keys under the streamer's hand the moment a run
 50	 * starts. Only on a change from nothing to something: a snapshot landing
 51	 * is not a reason to yank the deck away from whatever it was showing.
 52	 */
 53	let wasAttached: string | null = null;
 54	store.subscribe((s) => {
 55	  if (s.attached && !wasAttached)
 56	    for (const d of streamDeck.devices) void streamDeck.profiles.switchToProfile(d.id, PROFILE_NAME).catch(() => {});
 57	  wasAttached = s.attached;
 58	});
 59	
 60	// The Run inspector's list is only as fresh as the last appear; a run
 61	// starting or ending while the picker is open moves it without the
 62	// streamer closing and reopening the page.
 63	let lastRuns: DeckState["runs"] | null = null;
 64	store.subscribe((s) => {
 65	  if (s.runs === lastRuns) return;
 66	  lastRuns = s.runs;
 67	  if (streamDeck.ui.action) void streamDeck.ui.sendToPropertyInspector({ t: "runs", runs: runsForInspector(s.runs), pinned: s.pinned });
 68	});
 69	
 70	/**
 71	 * Switching the deck on.
 72	 *
 73	 * The address is read again first, so the one the streamer last typed is the
 74	 * one dialed. Reconnecting through drops after that is the wire's own job.
 75	 */
 76	export function turnOn(): void {
 77	  if (store.state.on) return;
 78	  store.dispatch({ t: "on", on: true });
 79	  void (async () => {
 80	    await readGlobals();
 81	    streamDeck.logger.info("on: connecting");
 82	    wire.connect();
 83	  })();
 84	}
 85	
 86	/** Switching it off, by a press or - with `idle` - by the deck's own timer. */
 87	export function turnOff(idle = false): void {
 88	  wire.disconnect();
 89	  store.dispatch({ t: "on", on: false, idle });
 90	  streamDeck.logger.info(idle ? "off: idle for thirty minutes" : "off: by request");
 91	}
 92	
 93	/** Tells whichever inspector is open where it is pointed and whether anyone is signed in. */
 94	export async function sayWho(): Promise<void> {
 95	  await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: loadSession() !== null, apiBase });
 96	}
 97	
 98	function applyGlobals(g: Globals): void {
 99	  apiBase = normalizeBase(g.apiBase ?? "") || DEFAULT_API;
100	  // Only on a change: this fires from the plugin's own write of a pin as
101	  // much as from another surface's, and a pin already applied locally
102	  // should not force the run's snapshot to reload for nothing.
103	  if (g.pinned !== undefined && g.pinned !== store.state.pinned) store.dispatch({ t: "pin", id: g.pinned });
104	}
105	
106	async function readGlobals(): Promise<void> {
107	  applyGlobals(await streamDeck.settings.getGlobalSettings<Globals>());
108	}
109	
110	// A deck holding no run for half an hour closes its own socket rather than
111	// sitting on one all night. A deck following a run never times out.
112	let idleSince: number | null = null;
113	let idleTimer: ReturnType<typeof setTimeout> | null = null;
114	store.subscribe((state) => {
115	  const now = Date.now();
116	  const deadline = idleDeadline(state, idleSince ?? now);
117	  if (deadline === null) {
118	    idleSince = null;
119	    if (idleTimer) clearTimeout(idleTimer);
120	    idleTimer = null;
121	    return;
122	  }
123	  if (idleTimer) return;
124	  idleSince = now;
125	  idleTimer = setTimeout(() => {
126	    idleTimer = null;
127	    turnOff(true);
128	  }, deadline - now);
129	});
130	
131	/**
132	 * The device flow's two lines, as the inspector needs them: the page and the code.
133	 *
134	 * `deviceFlow` writes for a terminal, two spaces and a label per line.
135	 * Exported so a test can hold this against the lines the flow actually
136	 * says - the inspector shows nothing at all if the two stop matching,
137	 * and nothing at all is a sign-in that looks like it hung.
138	 */
139	export function codeFromLines(): (line: string) => void {
140	  let code: string | null = null;
141	  let url: string | null = null;
142	  let sent = false;
143	  return (line) => {
144	    code = /^ {2}Code {2}(\S.*)$/.exec(line)?.[1]?.trim() ?? code;
145	    url = /^ {2}Open {2}(\S+)$/.exec(line)?.[1] ?? url;
146	    // Once. The flow keeps talking after those two lines - a blank, then
147	    // what a terminal should do while it waits - and every line after them
148	    // still has both halves in hand.
149	    if (code && url && !sent) {
150	      sent = true;
151	      void streamDeck.ui.sendToPropertyInspector({ t: "code", code, url });
152	    }
153	  };
154	}
155	
156	streamDeck.ui.onSendToPlugin<{ t?: string; id?: string | null }>(async (ev) => {
157	  switch (ev.payload?.t) {
158	    case "pin":
159	      await pin(ev.payload?.id ?? null);
160	      break;
161	    case "signin":
162	      try {
163	        streamDeck.logger.info("sign-in: starting the device flow");
164	        await signIn({ apiBase }, codeFromLines(), () => {});
165	        store.dispatch({ t: "session", state: "ok" });
166	        streamDeck.logger.info("sign-in: done");
167	        // Signed in is not connected: the streamer presses Connect.
168	        await streamDeck.ui.sendToPropertyInspector({ t: "who", name: "you", signedIn: true, apiBase });
169	      } catch (e) {
170	        // The reason goes back to the inspector, not only to the log: the
171	        // streamer is looking at the button they pressed, and a status line
172	        // that flips back to "Not signed in" tells them nothing.
173	        const error = e instanceof Error ? e.message : "unknown";
174	        streamDeck.logger.error(`sign-in: failed (${error})`);
175	        await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase, error });
176	      }
177	      break;
178	    case "signout":
179	      turnOff();
180	      signOut();
181	      store.dispatch({ t: "session", state: "none" });
182	      streamDeck.logger.info("signed out");
183	      await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase });
184	      break;
185	    case "reconnect":
186	      turnOff();
187	      turnOn();
188	      break;
189	    default:
190	      break;
191	  }
192	});
193	
194	streamDeck.logger.setLevel("info");
195	streamDeck.settings.onDidReceiveGlobalSettings<Globals>((ev) => applyGlobals(ev.settings));
196	
197	// A flash lasts three seconds and nothing else clears it; the tick is what
198	// puts a refused key back to what it was saying.
199	setInterval(() => store.dispatch({ t: "tick" }), 1000);
200	
201	for (const a of [new Next(), new Press(), new Roll(), new Undo(), new Run(), new Metric(), new Connect(), new Setup()]) {
202	  streamDeck.actions.registerAction(a);
203	}
204	
205	void streamDeck.connect().then(async () => {
206	  // Launch is quiet: the settings, the session, and nothing else. No socket
207	  // and no token refresh until the streamer presses Connect.
208	  await readGlobals();
209	  const signedIn = loadSession() !== null;
210	  store.dispatch({ t: "session", state: signedIn ? "ok" : "none" });
211	  streamDeck.logger.info(`launched: ${signedIn ? "signed in" : "not signed in"}, not connected`);
212	});

