 1	import { deviceFlow } from "@runlog/session";
 2	import { describe, expect, it, vi } from "vitest";
 3	
 4	/**
 5	 * `plugin.ts` is the whole plugin: it registers eight actions, opens a wire
 6	 * and dials the Stream Deck software the moment it is imported. The SDK and
 7	 * the two modules that reach outside are faked so importing it here does
 8	 * nothing but build the module, and `sent` is what an inspector would have
 9	 * been told.
10	 */
11	const mock = vi.hoisted(() => ({ sent: [] as unknown[] }));
12	vi.mock("@elgato/streamdeck", () => {
13	  class SingletonAction {}
14	  return {
15	    default: {
16	      logger: { setLevel: () => {}, info: () => {}, error: () => {} },
17	      ui: {
18	        action: null,
19	        onSendToPlugin: () => {},
20	        sendToPropertyInspector: async (m: unknown) => {
21	          mock.sent.push(m);
22	        },
23	      },
24	      settings: { getGlobalSettings: async () => ({}), onDidReceiveGlobalSettings: () => {} },
25	      actions: { registerAction: () => {} },
26	      profiles: { switchToProfile: async () => {} },
27	      devices: [],
28	      connect: async () => {},
29	    },
30	    action: () => (target: unknown) => target,
31	    SingletonAction,
32	  };
33	});
34	vi.mock("./socket.ts", () => ({ openWire: () => ({ connect: () => {}, disconnect: () => {}, press: () => null }) }));
35	// Never the real session file: this test signs nobody in and must not read
36	// the deck's own rotating token off disk.
37	vi.mock("./session.ts", () => ({
38	  loadSession: () => null,
39	  normalizeBase: (s: string) => s,
40	  signIn: async () => {},
41	  signOut: () => {},
42	}));
43	
44	// The module opens a one-second tick at import; a fake clock swallows it,
45	// and nothing below waits on a timer.
46	vi.useFakeTimers();
47	const { codeFromLines } = await import("./plugin.ts");
48	vi.useRealTimers();
49	
50	describe("the sign-in code the inspector shows", () => {
51	  it("is read off the lines the device flow actually says", async () => {
52	    const say = codeFromLines();
53	    await deviceFlow("client_deck", "https://api.workos.test", {
54	      fetch: async (url) =>
55	        String(url).includes("/authorize/device")
56	          ? new Response(
57	              JSON.stringify({
58	                device_code: "d",
59	                user_code: "ABCD-EFGH",
60	                verification_uri: "https://workos.test/device",
61	                interval: 0,
62	                expires_in: 60,
63	              }),
64	            )
65	          : new Response(JSON.stringify({ access_token: "a.b.c", refresh_token: "r" })),
66	      sleep: async () => {},
67	      say,
68	      open: () => {},
69	      now: () => Date.now(),
70	    });
71	
72	    // Both halves, once, in the one message: the inspector has nothing to
73	    // show until it has the page as well as the code.
74	    expect(mock.sent).toEqual([{ t: "code", code: "ABCD-EFGH", url: "https://workos.test/device" }]);
75	  });
76	
77	  it("says nothing for lines that carry neither", () => {
78	    mock.sent = [];
79	    const say = codeFromLines();
80	    say("");
81	    say("Waiting for you to confirm it there. Ctrl-C gives up.");
82	    expect(mock.sent).toEqual([]);
83	  });
84	});

