  1	import type { Face, Tone } from "./state.ts";
  2	
  3	/**
  4	 * A key face as SVG.
  5	 *
  6	 * SVG, because it needs no rasterizer and no native module in a package
  7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
  8	 * rejects a raw SVG string despite the documentation. 144 square is the
  9	 * @2x size; the software scales it to any key.
 10	 *
 11	 * The palette is the app's own: celadon for a live key, kiln for a
 12	 * refusal, the muted ink for a key with nothing to do. System sans, since
 13	 * a font in an SVG would have to travel as base64 on every redraw.
 14	 */
 15	const TONE: Record<Tone, { ground: string; ink: string; edge: string }> = {
 16	  live: { ground: "#1e2f27", ink: "#e7eae6", edge: "#8cc3a6" },
 17	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733" },
 18	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
 19	};
 20	
 21	const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
 22	
 23	/**
 24	 * Glyph widths in em for the system sans at weight 600 - Segoe UI Semibold
 25	 * on Windows, and near enough everywhere else. Counting characters was
 26	 * pessimistic: "connected" is nine narrow letters and fits at 26, but a
 27	 * count of ten sends it to 22. So the face measures instead, in classes
 28	 * coarse enough to read and close enough that the rendered ink stays
 29	 * inside the frame.
 30	 */
 31	const EM: Record<string, number> = {};
 32	for (const c of "ijl'.,:;!| ") EM[c] = 0.28;
 33	for (const c of "ftrI") EM[c] = 0.36;
 34	for (const c of "mw") EM[c] = 0.85;
 35	for (const c of "MW") EM[c] = 0.92;
 36	EM["…"] = 0.9;
 37	
 38	function em(ch: string): number {
 39	  const known = EM[ch];
 40	  if (known !== undefined) return known;
 41	  if (/[0-9a-z]/.test(ch)) return 0.55;
 42	  if (/[A-Z]/.test(ch)) return 0.68;
 43	  return 0.6;
 44	}
 45	
 46	/** How wide a line of text draws, in px, at this font size. */
 47	export function measure(text: string, size: number): number {
 48	  let w = 0;
 49	  for (const ch of text) w += em(ch);
 50	  return w * size;
 51	}
 52	
 53	/**
 54	 * The frame's usable width. 144 less 8 either side: the stroke is 3px wide
 55	 * centered at x=3, so 8 leaves 5px of clear ground inside it. Text is
 56	 * centered on 72, so a line no wider than this never reaches x=8 or x=136.
 57	 */
 58	const LINE = 144 - 2 * 8;
 59	const MAX_LINES = 3;
 60	
 61	/**
 62	 * The `when` line's own type: 16px monospace, a flat 0.6em per glyph rather
 63	 * than the title's per-glyph measurement. 128px at 16px holds 13 characters
 64	 * (128 / (16 * 0.6) = 13.33); a fourteenth never fits. 18px held only
 65	 * eleven, which cut "press Connect" - the one instruction on the key that
 66	 * has to be read whole - down to "press Conne…".
 67	 */
 68	const WHEN_SIZE = 16;
 69	const WHEN_MAX = 13;
 70	
 71	/**
 72	 * Fit `when` to `WHEN_MAX` characters. A word boundary that still leaves at
 73	 * least six characters reads better than a stub, so that is tried first;
 74	 * otherwise the cut falls back to characters. Either way an "…" marks what
 75	 * was cut, and nothing kept ever runs past `WHEN_MAX`.
 76	 */
 77	function ellipsizeWhen(text: string): string {
 78	  if (text.length <= WHEN_MAX) return text;
 79	  let cut = "";
 80	  for (const word of text.split(" ")) {
 81	    const next = cut ? `${cut} ${word}` : word;
 82	    if (next.length > WHEN_MAX) break;
 83	    cut = next;
 84	  }
 85	  if (cut.length < 6) cut = text.slice(0, WHEN_MAX);
 86	  return `${cut}…`;
 87	}
 88	
 89	/**
 90	 * Greedy word wrap by measured width: pack words onto a line up to `width`
 91	 * px at `size`, at most `lines` lines. A word too wide for a line of its
 92	 * own is broken by characters and carries on below. The last line gets an
 93	 * ellipsis if any text was left over.
 94	 */
 95	export function wrap(text: string, size: number, width = LINE, lines = MAX_LINES): string[] {
 96	  const words = text.split(/\s+/).filter(Boolean);
 97	  const out: string[] = [];
 98	  let i = 0;
 99	  while (i < words.length && out.length < lines) {
100	    const word = words[i]!;
101	    if (measure(word, size) > width) {
102	      let cut = "";
103	      for (const ch of word) {
104	        if (measure(cut + ch, size) > width) break;
105	        cut += ch;
106	      }
107	      // One glyph always goes, or a face narrower than its own type would
108	      // loop here forever.
109	      if (cut === "") cut = [...word][0]!;
110	      out.push(cut);
111	      words[i] = word.slice(cut.length);
112	      continue;
113	    }
114	    let line = word;
115	    i++;
116	    while (i < words.length && measure(line + " " + words[i], size) <= width) {
117	      line += " " + words[i];
118	      i++;
119	    }
120	    out.push(line);
121	  }
122	  if (i < words.length && out.length > 0) {
123	    let last = out[out.length - 1]!;
124	    while (last.length > 0 && measure(last + "…", size) > width) last = last.slice(0, -1);
125	    out[out.length - 1] = last + "…";
126	  }
127	  return out;
128	}
129	
130	/**
131	 * The type scale, biggest first. Every step gets the same three lines and
132	 * the same 128px; what changes is how much of a phrase that holds. A title
133	 * takes the first step that keeps every word whole; one too long for the
134	 * last step is wrapped to it anyway and ellipsized rather than drawn over
135	 * the frame.
136	 */
137	const SCALE = [40, 34, 30, 26, 22] as const;
138	
139	/** Whether wrapping at this size keeps every word of the phrase. */
140	function whole(text: string, size: number): boolean {
141	  return wrap(text, size).join(" ") === text.split(/\s+/).filter(Boolean).join(" ");
142	}
143	
144	function typeset(text: string): { lines: string[]; size: number } {
145	  const size = SCALE.find((s) => whole(text, s)) ?? SCALE[SCALE.length - 1]!;
146	  return { lines: wrap(text, size), size };
147	}
148	
149	export function faceImage(face: Face): string {
150	  const t = TONE[face.tone];
151	  const { lines, size } = typeset(face.title);
152	  const top = 72 - ((lines.length - 1) * size * 1.15) / 2 + (face.when ? -10 : 0);
153	  // One positioned <text> per line, baseline given outright: the software
154	  // draws SVG with a renderer that honors x and y on a text element and
155	  // little else - a tspan with its own position, or a dominant-baseline,
156	  // left every title off the key while the small line beneath it showed.
157	  // 0.36em is where the middle of a semibold sans sits above its baseline.
158	  const spans = lines
159	    .map(
160	      (l, i) =>
161	        `<text class="t" x="72" y="${(top + i * size * 1.15 + size * 0.36).toFixed(1)}" text-anchor="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="Segoe UI, Helvetica Neue, Helvetica, Arial, sans-serif">${esc(l)}</text>`,
162	    )
163	    .join("");
164	  const when = face.when
165	    ? `<text x="72" y="126" text-anchor="middle" font-size="${WHEN_SIZE}" fill="${t.edge}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(ellipsizeWhen(face.when))}</text>`
166	    : "";
167	  const svg =
168	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
169	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
170	    // thing even when the drawn lines above cut it short.
171	    `<title>${esc(face.title)}</title>` +
172	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
173	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="3"/>` +
174	    spans +
175	    when +
176	    `</svg>`;
177	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
178	}

